def longest_no_stop(s):
    best=(0,0,0)
    for f in range(3):
        last=f
        i=f
        while i<len(s)-2:
            if s[i:i+3] in ('TAA','TAG','TGA'):
                if i-last>best[2]-best[1]:
                    best=(last,i,f)
                last=i+3
            i+=3
        if len(s)-last>best[2]-best[1]:
            best=(last,len(s),f)
    return best
for lbl,s in (('fwd',seq),('rev',rc)):
    a,b,f=longest_no_stop(s)
    print(lbl,a,b,(b-a)//3,'frame',f)

